import React, { useState, useEffect } from "react";
import "./ViewTasks.css";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import StudentSidebar from "../components/StudentSidebar";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const ViewTasks = () => {
  const user = JSON.parse(localStorage.getItem('users'));
  const [student, setStudent] = useState(null);
  const [group, setGroup] = useState(null);
  const [milestones, setMilestones] = useState([]);
  const [tasks, setTasks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const navigate = useNavigate();

  // State for new milestone input
  const [newMilestone, setNewMilestone] = useState({
    title: "",
    dueDate: "",
    status: "Pending"
  });

  // State for new task input
  const [newTask, setNewTask] = useState({
    title: "",
    status: "Pending",
    milestoneId: ""
  });

  // Toggle sidebar
  const toggleSidebar = () => {
    setSidebarOpen(!sidebarOpen);
  };

  // Fetch student data
  useEffect(() => {
    if (!user) {
      navigate('/login');
      return;
    }

    const fetchStudentData = async () => {
      try {
        const response = await axios.get(`http://localhost:5000/api/student/user/${user.id}`);
        setStudent(response.data);

        if (response.data.isGrouped) {
          const groupResponse = await axios.get(`http://localhost:5000/api/group/student/${response.data.regNo}`);
          setGroup(groupResponse.data);

          const milestonesResponse = await axios.get(`http://localhost:5000/api/milestone/groupNo/${groupResponse.data.groupNo}`);
          setMilestones(milestonesResponse.data);

          const allTasks = [];
          for (const milestone of milestonesResponse.data) {
            const tasksResponse = await axios.get(`http://localhost:5000/api/task/milestone/${milestone._id}`);
            allTasks.push(...tasksResponse.data);
          }
          setTasks(allTasks);
        }
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchStudentData();
  }, [user, navigate]);

  // Add new milestone
  const handleAddMilestone = async () => {
    if (!newMilestone.title.trim() || !newMilestone.dueDate) {
      alert("Please fill in all milestone fields.");
      return;
    }

    try {
      const milestoneData = {
        ...newMilestone,
        projectID: group.projectID
      };

      const response = await axios.post("http://localhost:5000/api/milestone", milestoneData);
      setMilestones([...milestones, response.data]);
      setNewMilestone({ title: "", dueDate: "", status: "Pending" });
    } catch (err) {
      alert("Failed to add milestone: " + err.message);
    }
  };

  // Add new task
  const handleAddTask = async (milestoneId) => {
    if (!newTask.title.trim()) {
      alert("Please enter a task title.");
      return;
    }

    try {
      const taskData = {
        ...newTask,
        milestoneId,
        uploadedBy: student.studentName
      };

      const response = await axios.post("http://localhost:5000/api/task", taskData);
      setTasks([...tasks, response.data]);
      setNewTask({ title: "", status: "Pending", milestoneId: "" });
    } catch (err) {
      alert("Failed to add task: " + err.message);
    }
  };

  // Update task status
  const handleUpdateTaskStatus = async (taskId, newStatus) => {
    try {
      await axios.patch(`http://localhost:5000/api/task/${taskId}`, { status: newStatus });

      setTasks(tasks.map(task => 
        task._id === taskId ? { ...task, status: newStatus } : task
      ));
    } catch (err) {
      alert("Failed to update task status: " + err.message);
    }
  };

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;

  if (!student?.isGrouped || !group) {
    return (
      <div className="tasks-container">
        <Navbar toggleSidebar={toggleSidebar} sidebarOpen={sidebarOpen} />
        <div className="content-wrapper">
          <StudentSidebar open={sidebarOpen} />
          <div className={`main-content ${sidebarOpen ? '' : 'collapsed'}`}>
            <h1 className="tasks-title">Manage Milestones and Tasks</h1>
            <div className="not-grouped-message">
              <p>You are not currently in a group. Please join or create a group to view and manage tasks.</p>
            </div>
          </div>
        </div>
        <Footer />
      </div>
    );
  }

  return (
    <div className="tasks-container">
      <Navbar toggleSidebar={toggleSidebar} sidebarOpen={sidebarOpen} />
      <div className="content-wrapper">
        <StudentSidebar open={sidebarOpen} />
        <div className={`main-content ${sidebarOpen ? '' : 'collapsed'}`}>
          <h1 className="tasks-title">Manage Milestones and Tasks</h1>
          <p className="group-info">Group: {group.groupNo} | Project: {group.projectID}</p>

          {/* Add Milestone Section */}
          <div className="milestone-section">
            <h2>Add New Milestone</h2>
            <input
              type="text"
              value={newMilestone.title}
              onChange={(e) => setNewMilestone({ ...newMilestone, title: e.target.value })}
              placeholder="Milestone title"
            />
            <input
              type="date"
              value={newMilestone.dueDate}
              onChange={(e) => setNewMilestone({ ...newMilestone, dueDate: e.target.value })}
              placeholder="Due date"
            />
            <button onClick={handleAddMilestone}>Add Milestone</button>
          </div>

          {/* List of Milestones with Tasks */}
          <div className="milestone-list">
            {milestones.map((milestone) => (
              <div key={milestone._id} className="milestone-item">
                <h2>{milestone.title}</h2>
                <p>Due Date: {new Date(milestone.dueDate).toLocaleDateString()} | Status: {milestone.status}</p>

                {/* Add Task Section */}
                <div className="task-section">
                  <h3>Add New Task</h3>
                  <input
                    type="text"
                    value={newTask.title}
                    onChange={(e) => setNewTask({ ...newTask, title: e.target.value, milestoneId: milestone._id })}
                    placeholder="Task title"
                  />
                  <button className="task-button" onClick={() => handleAddTask(milestone._id)}>
                    Add Task
                  </button>
                </div>

                {/* Tasks Table */}
                <div className="tasks-table">
                  <h3>Tasks</h3>
                  <table>
                    <thead>
                      <tr>
                        <th>Task</th>
                        <th>Uploaded By</th>
                        <th>Status</th>
                        <th>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {tasks
                        .filter(task => task.milestoneId === milestone._id)
                        .map((task) => (
                          <tr key={task._id}>
                            <td>{task.title}</td>
                            <td>{task.uploadedBy}</td>
                            <td>{task.status}</td>
                            <td>
                              {task.status !== "Completed" && (
                                <button
                                  className="mark-completed-button"
                                  onClick={() => handleUpdateTaskStatus(task._id, "Completed")}
                                >
                                  Mark as Completed
                                </button>
                              )}
                            </td>
                          </tr>
                        ))}
                    </tbody>
                  </table>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ViewTasks;
